mapper.select:
SELECT COUNT(*)
FROM inventory
WHERE
    EXISTS (
        SELECT 1 FROM product p
        WHERE p.id = inventory.product_id
          AND p.code = #{code}
    )
  AND production_date = #{date}

mapper.update:
update inventory
quantity=#{quantity}, update_time=#{updateTime},
where product_id=#{productId} and warehouse_id=#{warehouseId} and batch_no=#{batchNo}

mapper.select:
SELECT * FROM inventory
WHERE product_id = #{productId} AND warehouse_id = #{warehouseId}
ORDER BY expiration_date ASC
